#!/usr/bin/env node
// Validates every task directory next to this script:
//   - task.json has the required fields and a matching id
//   - the fixture as shipped fails `node --test test/*.test.js`
//   - the same fixture with src/ replaced by reference/src/ passes
//   - no node_modules anywhere, directory under 150 KB
// Prints one line per task and exits non-zero on any violation.
// Usage: node validate.mjs [task-id ...]

import { spawnSync } from 'node:child_process';
import { cpSync, mkdtempSync, readdirSync, readFileSync, rmSync, statSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = dirname(fileURLToPath(import.meta.url));
const MAX_BYTES = 150 * 1024;
const REQUIRED_CHECK_IDS = ['tests-pass', 'no-dependencies'];

/**
 * Walks a directory tree, yielding every regular file path.
 * @param {string} dir Directory to walk.
 * @returns {Generator<string>} Absolute file paths.
 */
function* walk(dir) {
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const full = join(dir, entry.name);
    if (entry.isDirectory()) yield* walk(full);
    else if (entry.isFile()) yield full;
  }
}

/**
 * Total size of a directory tree in bytes.
 * @param {string} dir Directory to measure.
 * @returns {number} Sum of file sizes.
 */
function dirBytes(dir) {
  let total = 0;
  for (const file of walk(dir)) total += statSync(file).size;
  return total;
}

/**
 * Counts static assertion call sites in a task's test files.
 * @param {string} taskDir Task root.
 * @returns {number} Number of `assert(...)` / `assert.xxx(...)` call sites.
 */
function countAssertions(taskDir) {
  let count = 0;
  for (const file of walk(join(taskDir, 'test'))) {
    if (!file.endsWith('.test.js')) continue;
    const source = readFileSync(file, 'utf8');
    const matches = source.match(/\bassert(?:\.[A-Za-z]+)?\s*\(/g);
    count += matches ? matches.length : 0;
  }
  return count;
}

/**
 * Runs the task test command in a directory.
 * @param {string} cwd Directory to run in.
 * @returns {{status: number, output: string}} Exit status and combined output.
 */
function runTests(cwd) {
  const result = spawnSync('sh', ['-c', 'node --test test/*.test.js'], {
    cwd,
    encoding: 'utf8',
    env: { ...process.env, NODE_OPTIONS: '' },
  });
  return { status: result.status ?? 1, output: `${result.stdout ?? ''}${result.stderr ?? ''}` };
}

const problems = [];
const only = new Set(process.argv.slice(2));
const taskDirs = readdirSync(ROOT, { withFileTypes: true })
  .filter((e) => e.isDirectory() && !e.name.startsWith('.'))
  .map((e) => e.name)
  .filter((name) => only.size === 0 || only.has(name))
  .sort();

if (taskDirs.length === 0) problems.push('no task directories found');

for (const name of taskDirs) {
  const taskDir = join(ROOT, name);
  /** @type {string[]} */
  const local = [];

  let task;
  try {
    task = JSON.parse(readFileSync(join(taskDir, 'task.json'), 'utf8'));
  } catch (error) {
    problems.push(`${name}: task.json unreadable (${error.message})`);
    continue;
  }

  if (task.id !== `code:${name}`) local.push(`id ${JSON.stringify(task.id)} !== "code:${name}"`);
  if (![2, 3, 4].includes(task.tier)) local.push(`tier ${JSON.stringify(task.tier)} is not 2, 3 or 4`);
  for (const field of ['domain', 'title', 'prompt']) {
    if (typeof task[field] !== 'string' || task[field].length === 0) local.push(`missing ${field}`);
  }
  if (typeof task.heldOut !== 'boolean') local.push('heldOut is not a boolean');
  if (!Array.isArray(task.immutable) || !task.immutable.includes('test') || !task.immutable.includes('package.json')) {
    local.push('immutable must list "test" and "package.json"');
  }
  if (!Array.isArray(task.checks)) local.push('checks is not an array');
  else {
    for (const id of REQUIRED_CHECK_IDS) {
      if (!task.checks.some((c) => c && c.id === id)) local.push(`missing check ${id}`);
    }
    for (const check of task.checks) {
      for (const field of ['id', 'outcome', 'run']) {
        if (typeof check?.[field] !== 'string' || check[field].length === 0) {
          local.push(`check ${JSON.stringify(check?.id)} missing ${field}`);
        }
      }
    }
  }
  for (const forbidden of ['tier', 'held out', 'held-out', 'reference solution']) {
    if (typeof task.prompt === 'string' && task.prompt.toLowerCase().includes(forbidden)) {
      local.push(`prompt leaks "${forbidden}"`);
    }
  }

  const pkgPath = join(taskDir, 'package.json');
  try {
    const pkg = JSON.parse(readFileSync(pkgPath, 'utf8'));
    if (pkg.name !== name) local.push(`package.json name ${JSON.stringify(pkg.name)} !== ${JSON.stringify(name)}`);
    if (pkg.type !== 'module') local.push('package.json type must be "module"');
    if (pkg.private !== true) local.push('package.json private must be true');
    if (pkg.scripts?.test !== 'node --test test/*.test.js') local.push('package.json test script mismatch');
    if (pkg.dependencies || pkg.devDependencies) local.push('package.json declares dependencies');
  } catch (error) {
    local.push(`package.json unreadable (${error.message})`);
  }

  for (const file of walk(taskDir)) {
    const rel = relative(taskDir, file);
    if (rel.split('/').includes('node_modules')) local.push(`node_modules present at ${rel}`);
  }

  const bytes = dirBytes(taskDir);
  if (bytes > MAX_BYTES) local.push(`directory is ${bytes} bytes (limit ${MAX_BYTES})`);

  const testFiles = readdirSync(join(taskDir, 'test')).filter((f) => f.endsWith('.test.js'));
  if (testFiles.length === 0) local.push('no test/*.test.js files');

  const assertions = countAssertions(taskDir);
  if (assertions < 25 || assertions > 60) local.push(`assertion count ${assertions} outside 25..60`);

  let preState = 'skip';
  let reference = 'skip';
  if (testFiles.length > 0) {
    const work = mkdtempSync(join(tmpdir(), `pg-${name}-`));
    try {
      cpSync(taskDir, work, { recursive: true, filter: (src) => !relative(taskDir, src).startsWith('reference') });
      const pre = runTests(work);
      preState = pre.status === 0 ? 'pass' : 'fail';
      if (pre.status === 0) local.push(`pre-state passed its tests\n${pre.output.slice(-800)}`);

      rmSync(join(work, 'src'), { recursive: true, force: true });
      cpSync(join(taskDir, 'reference', 'src'), join(work, 'src'), { recursive: true });
      const ref = runTests(work);
      reference = ref.status === 0 ? 'pass' : 'fail';
      if (ref.status !== 0) local.push(`reference failed its tests\n${ref.output.slice(-4000)}`);
    } finally {
      rmSync(work, { recursive: true, force: true });
    }
  }

  console.log(
    `code:${name} tier=${task.tier} preState=${preState} reference=${reference} assertions=${assertions} bytes=${bytes}`,
  );
  for (const problem of local) problems.push(`${name}: ${problem}`);
}

if (problems.length > 0) {
  console.error(`\n${problems.length} problem(s):`);
  for (const problem of problems) console.error(`  - ${problem}`);
  process.exit(1);
}
console.log(`\nOK: ${taskDirs.length} task(s) validated.`);

/**
 * Set algebra over half-open integer intervals `[start, end)`.
 *
 * A normalised list is sorted by start, holds no empty interval, and no two of
 * its intervals overlap or touch. Every exported function validates its inputs
 * and returns freshly allocated arrays.
 */

/** Message used when a value is not an array of intervals. */
const NOT_A_LIST = 'interval list must be an array';
/** Message used when an element is not a two-element array. */
const NOT_A_PAIR = 'interval must be a two-element array';
/** Message used when a bound is not a safe integer. */
const NOT_INTEGER = 'interval bounds must be safe integers';
/** Message used when a start is greater than its end. */
const INVERTED = 'interval start must not exceed end';

/**
 * Validates one interval and returns a copy of it.
 * @param {unknown} interval Candidate interval.
 * @returns {[number, number]} Copy of the validated interval.
 * @throws {TypeError} When the interval is not a pair of safe integers.
 * @throws {RangeError} When start is greater than end.
 */
function checkInterval(interval) {
  if (!Array.isArray(interval) || interval.length !== 2) throw new TypeError(NOT_A_PAIR);
  const [start, end] = interval;
  if (!Number.isSafeInteger(start) || !Number.isSafeInteger(end)) throw new TypeError(NOT_INTEGER);
  if (start > end) throw new RangeError(INVERTED);
  return [start, end];
}

/**
 * Validates a list of intervals and returns copies of its non-empty members.
 * @param {unknown} intervals Candidate interval list.
 * @returns {Array<[number, number]>} Copies of the non-empty intervals.
 * @throws {TypeError} When the list or any member is malformed.
 * @throws {RangeError} When any member is inverted.
 */
function checkList(intervals) {
  if (!Array.isArray(intervals)) throw new TypeError(NOT_A_LIST);
  const out = [];
  for (const interval of intervals) {
    const pair = checkInterval(interval);
    if (pair[0] < pair[1]) out.push(pair);
  }
  return out;
}

/**
 * Sorts and coalesces validated intervals in place.
 * @param {Array<[number, number]>} pairs Validated non-empty intervals.
 * @returns {Array<[number, number]>} Normalised list.
 */
function coalesce(pairs) {
  pairs.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  const out = [];
  for (const [start, end] of pairs) {
    const last = out[out.length - 1];
    if (last !== undefined && start <= last[1]) {
      if (end > last[1]) last[1] = end;
    } else {
      out.push([start, end]);
    }
  }
  return out;
}

/**
 * Normalises a list of intervals: drops empties, sorts, and coalesces
 * overlapping or touching intervals.
 * @param {unknown} intervals Interval list.
 * @returns {Array<[number, number]>} Normalised list.
 */
export function normalize(intervals) {
  return coalesce(checkList(intervals));
}

/**
 * Union of two interval lists.
 * @param {unknown} a First interval list.
 * @param {unknown} b Second interval list.
 * @returns {Array<[number, number]>} Normalised union.
 */
export function merge(a, b) {
  return coalesce([...checkList(a), ...checkList(b)]);
}

/**
 * Intersection of two interval lists. Touching intervals do not intersect.
 * @param {unknown} a First interval list.
 * @param {unknown} b Second interval list.
 * @returns {Array<[number, number]>} Normalised intersection.
 */
export function intersect(a, b) {
  const left = coalesce(checkList(a));
  const right = coalesce(checkList(b));
  const out = [];
  let i = 0;
  let j = 0;
  while (i < left.length && j < right.length) {
    const start = Math.max(left[i][0], right[j][0]);
    const end = Math.min(left[i][1], right[j][1]);
    if (start < end) out.push([start, end]);
    if (left[i][1] <= right[j][1]) i += 1;
    else j += 1;
  }
  return out;
}

/**
 * Relative complement `a \ b`.
 * @param {unknown} a Interval list to subtract from.
 * @param {unknown} b Interval list to remove.
 * @returns {Array<[number, number]>} Normalised difference.
 */
export function subtract(a, b) {
  const left = coalesce(checkList(a));
  const right = coalesce(checkList(b));
  const out = [];
  let j = 0;
  for (const [start, end] of left) {
    let cursor = start;
    let k = j;
    while (k < right.length && right[k][1] <= cursor) k += 1;
    j = k;
    while (k < right.length && right[k][0] < end) {
      if (right[k][0] > cursor) out.push([cursor, right[k][0]]);
      cursor = Math.max(cursor, right[k][1]);
      if (cursor >= end) break;
      k += 1;
    }
    if (cursor < end) out.push([cursor, end]);
  }
  return out;
}

/**
 * Total length covered by a list of intervals, counting overlaps once.
 * @param {unknown} intervals Interval list.
 * @returns {number} Number of integers covered.
 */
export function coverage(intervals) {
  let total = 0;
  for (const [start, end] of coalesce(checkList(intervals))) total += end - start;
  return total;
}

import { test } from 'node:test';
import assert from 'node:assert/strict';

import { coverage, intersect, merge, normalize, subtract } from '../src/intervals.js';

/** Lower bound of the universe used by the model-based checks. */
const LO = -40;
/** Upper bound (exclusive) of the universe used by the model-based checks. */
const HI = 40;

/**
 * Deterministic 32-bit PRNG.
 * @param {number} seed Initial state.
 * @returns {() => number} Generator returning floats in [0, 1).
 */
function mulberry32(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * Rasterises an interval list over the model universe.
 * @param {Array<[number, number]>} list Interval list.
 * @returns {Uint8Array} One byte per integer in [LO, HI).
 */
function raster(list) {
  const bits = new Uint8Array(HI - LO);
  for (const [start, end] of list) {
    for (let x = Math.max(start, LO); x < Math.min(end, HI); x += 1) bits[x - LO] = 1;
  }
  return bits;
}

/**
 * Converts a raster back into a normalised interval list.
 * @param {Uint8Array} bits Raster.
 * @returns {Array<[number, number]>} Normalised list.
 */
function unraster(bits) {
  const out = [];
  let run = -1;
  for (let i = 0; i <= bits.length; i += 1) {
    const on = i < bits.length && bits[i] === 1;
    if (on && run < 0) run = i;
    if (!on && run >= 0) {
      out.push([run + LO, i + LO]);
      run = -1;
    }
  }
  return out;
}

/**
 * Asserts that a list is normalised: sorted, non-empty, disjoint, non-touching.
 * @param {Array<[number, number]>} list List under test.
 * @param {string} label Assertion label.
 * @returns {void}
 */
function assertNormalised(list, label) {
  for (let i = 0; i < list.length; i += 1) {
    assert.ok(list[i][0] < list[i][1], `${label}: empty interval at ${i}`);
    if (i > 0) assert.ok(list[i - 1][1] < list[i][0], `${label}: not disjoint at ${i}`);
  }
}

/**
 * Builds a random interval list.
 * @param {() => number} rnd Generator.
 * @param {number} count How many intervals.
 * @returns {Array<[number, number]>} Random intervals, possibly empty ones.
 */
function randomList(rnd, count) {
  const out = [];
  for (let i = 0; i < count; i += 1) {
    const start = LO + Math.floor(rnd() * (HI - LO));
    const width = Math.floor(rnd() * 9);
    out.push([start, start + width]);
  }
  return out;
}

test('normalize sorts, drops empties, and coalesces overlapping and touching intervals', () => {
  const cases = [
    { input: [], expected: [] },
    { input: [[3, 3]], expected: [] },
    { input: [[5, 9]], expected: [[5, 9]] },
    { input: [[1, 3], [3, 5]], expected: [[1, 5]] },
    { input: [[1, 3], [4, 5]], expected: [[1, 3], [4, 5]] },
    { input: [[4, 5], [1, 3]], expected: [[1, 3], [4, 5]] },
    { input: [[0, 10], [2, 3]], expected: [[0, 10]] },
    { input: [[2, 3], [0, 10]], expected: [[0, 10]] },
    { input: [[1, 4], [2, 6], [6, 7], [9, 9]], expected: [[1, 7]] },
    { input: [[-8, -4], [-4, -1], [-1, 0]], expected: [[-8, 0]] },
    { input: [[2, 2], [2, 2]], expected: [] },
    { input: [[7, 8], [7, 8], [7, 8]], expected: [[7, 8]] },
  ];
  for (const { input, expected } of cases) {
    assert.deepEqual(normalize(input), expected, JSON.stringify(input));
  }
});

test('normalize is idempotent and leaves its argument untouched', () => {
  const input = [[5, 7], [1, 2], [6, 9]];
  const snapshot = JSON.parse(JSON.stringify(input));
  const once = normalize(input);
  assert.deepEqual(input, snapshot);
  assert.deepEqual(normalize(once), once);
  once[0][0] = 999;
  assert.deepEqual(input, snapshot);
});

test('normalize rejects malformed input with the specified error classes', () => {
  assert.throws(() => normalize('nope'), { name: 'TypeError', message: 'interval list must be an array' });
  assert.throws(() => normalize(null), { name: 'TypeError', message: 'interval list must be an array' });
  assert.throws(() => normalize([[1]]), { name: 'TypeError', message: 'interval must be a two-element array' });
  assert.throws(() => normalize([[1, 2, 3]]), { name: 'TypeError', message: 'interval must be a two-element array' });
  assert.throws(() => normalize([{ start: 1, end: 2 }]), { name: 'TypeError', message: 'interval must be a two-element array' });
  assert.throws(() => normalize([[1.5, 2]]), { name: 'TypeError', message: 'interval bounds must be safe integers' });
  assert.throws(() => normalize([[1, Number.NaN]]), { name: 'TypeError', message: 'interval bounds must be safe integers' });
  assert.throws(() => normalize([[0, Number.POSITIVE_INFINITY]]), { name: 'TypeError', message: 'interval bounds must be safe integers' });
  assert.throws(() => normalize([['1', 2]]), { name: 'TypeError', message: 'interval bounds must be safe integers' });
  assert.throws(() => normalize([[9, 4]]), { name: 'RangeError', message: 'interval start must not exceed end' });
  assert.throws(() => merge([[0, 1]], [[3, 2]]), { name: 'RangeError', message: 'interval start must not exceed end' });
  assert.throws(() => intersect([[0, 1]], 7), { name: 'TypeError', message: 'interval list must be an array' });
  assert.throws(() => subtract([[0, 1]], [[]]), { name: 'TypeError', message: 'interval must be a two-element array' });
  assert.throws(() => coverage([[Number.MAX_SAFE_INTEGER + 1, 0]]), { name: 'TypeError', message: 'interval bounds must be safe integers' });
});

test('merge unions both lists', () => {
  assert.deepEqual(merge([], []), []);
  assert.deepEqual(merge([[1, 4]], []), [[1, 4]]);
  assert.deepEqual(merge([], [[1, 4]]), [[1, 4]]);
  assert.deepEqual(merge([[1, 4]], [[4, 6]]), [[1, 6]]);
  assert.deepEqual(merge([[1, 4]], [[5, 6]]), [[1, 4], [5, 6]]);
  assert.deepEqual(merge([[10, 20], [0, 2]], [[2, 3], [19, 25]]), [[0, 3], [10, 25]]);
});

test('intersect keeps only shared points and never keeps touching endpoints', () => {
  assert.deepEqual(intersect([], [[0, 5]]), []);
  assert.deepEqual(intersect([[1, 3]], [[3, 5]]), []);
  assert.deepEqual(intersect([[1, 4]], [[3, 5]]), [[3, 4]]);
  assert.deepEqual(intersect([[0, 10]], [[2, 3], [4, 5]]), [[2, 3], [4, 5]]);
  assert.deepEqual(intersect([[0, 3], [4, 7]], [[2, 5]]), [[2, 3], [4, 5]]);
  assert.deepEqual(intersect([[-10, -2]], [[-5, 0]]), [[-5, -2]]);
  assert.deepEqual(intersect([[0, 6], [1, 2]], [[1, 9], [5, 5]]), [[1, 6]]);
});

test('subtract punches every hole and leaves the remainder normalised', () => {
  assert.deepEqual(subtract([[0, 10]], []), [[0, 10]]);
  assert.deepEqual(subtract([], [[0, 10]]), []);
  assert.deepEqual(subtract([[0, 10]], [[3, 5]]), [[0, 3], [5, 10]]);
  assert.deepEqual(subtract([[0, 10]], [[0, 10]]), []);
  assert.deepEqual(subtract([[0, 10]], [[-5, 20]]), []);
  assert.deepEqual(subtract([[0, 10]], [[10, 20]]), [[0, 10]]);
  assert.deepEqual(subtract([[0, 10]], [[0, 1], [9, 10]]), [[1, 9]]);
  assert.deepEqual(subtract([[0, 4], [6, 10]], [[2, 8]]), [[0, 2], [8, 10]]);
  assert.deepEqual(subtract([[0, 20]], [[1, 2], [4, 6], [7, 8]]), [[0, 1], [2, 4], [6, 7], [8, 20]]);
  assert.deepEqual(subtract([[-3, 3]], [[-1, 1]]), [[-3, -1], [1, 3]]);
});

test('coverage counts overlapping points once', () => {
  assert.equal(coverage([]), 0);
  assert.equal(coverage([[4, 4]]), 0);
  assert.equal(coverage([[0, 10], [2, 4]]), 10);
  assert.equal(coverage([[0, 3], [3, 6]]), 6);
  assert.equal(coverage([[-5, 5]]), 10);
});

test('operations agree with a rasterised model on adversarial random input', () => {
  const rnd = mulberry32(0xc0ffee);
  for (let round = 0; round < 300; round += 1) {
    const a = randomList(rnd, 1 + Math.floor(rnd() * 8));
    const b = randomList(rnd, 1 + Math.floor(rnd() * 8));
    const ra = raster(a);
    const rb = raster(b);
    const expectUnion = new Uint8Array(ra.length);
    const expectMeet = new Uint8Array(ra.length);
    const expectDiff = new Uint8Array(ra.length);
    for (let i = 0; i < ra.length; i += 1) {
      expectUnion[i] = ra[i] | rb[i];
      expectMeet[i] = ra[i] & rb[i];
      expectDiff[i] = ra[i] && !rb[i] ? 1 : 0;
    }
    const gotNorm = normalize(a);
    const gotUnion = merge(a, b);
    const gotMeet = intersect(a, b);
    const gotDiff = subtract(a, b);
    assertNormalised(gotNorm, `normalize round ${round}`);
    assertNormalised(gotUnion, `merge round ${round}`);
    assertNormalised(gotMeet, `intersect round ${round}`);
    assertNormalised(gotDiff, `subtract round ${round}`);
    assert.deepEqual(gotNorm, unraster(ra), `normalize round ${round}`);
    assert.deepEqual(gotUnion, unraster(expectUnion), `merge round ${round}`);
    assert.deepEqual(gotMeet, unraster(expectMeet), `intersect round ${round}`);
    assert.deepEqual(gotDiff, unraster(expectDiff), `subtract round ${round}`);
    assert.deepEqual(intersect(b, a), gotMeet, `intersect commutes round ${round}`);
    assert.equal(coverage(gotUnion), coverage(a) + coverage(b) - coverage(gotMeet), `inclusion-exclusion round ${round}`);
    assert.equal(coverage(gotDiff) + coverage(gotMeet), coverage(a), `partition round ${round}`);
    assert.deepEqual(intersect(gotDiff, b), [], `difference is disjoint from b round ${round}`);
  }
});

test('handles wide ranges and long lists without losing points', () => {
  const wide = [[-1000000, 1000000], [999999, 1000005]];
  assert.deepEqual(normalize(wide), [[-1000000, 1000005]]);
  assert.equal(coverage(wide), 2000005);
  const many = [];
  for (let i = 0; i < 500; i += 1) many.push([i * 3, i * 3 + 2]);
  assert.equal(normalize(many).length, 500);
  assert.equal(coverage(many), 1000);
  assert.deepEqual(subtract(many, [[0, 1500]]), normalize(many).filter(([start]) => start >= 1500));
  const alternating = [];
  for (let i = 0; i < 200; i += 1) alternating.push([-i, i + 1]);
  assert.deepEqual(normalize(alternating), [[-199, 201]]);
});

/**
 * Set algebra over half-open integer intervals `[start, end)`.
 */

/**
 * Normalises a list of intervals: drops empties, sorts, and coalesces
 * overlapping or touching intervals.
 * @param {unknown} intervals Interval list.
 * @returns {Array<[number, number]>} Normalised list.
 */
export function normalize(intervals) {
  throw new Error('not implemented');
}

/**
 * Union of two interval lists.
 * @param {unknown} a First interval list.
 * @param {unknown} b Second interval list.
 * @returns {Array<[number, number]>} Normalised union.
 */
export function merge(a, b) {
  throw new Error('not implemented');
}

/**
 * Intersection of two interval lists. Touching intervals do not intersect.
 * @param {unknown} a First interval list.
 * @param {unknown} b Second interval list.
 * @returns {Array<[number, number]>} Normalised intersection.
 */
export function intersect(a, b) {
  throw new Error('not implemented');
}

/**
 * Relative complement `a \ b`.
 * @param {unknown} a Interval list to subtract from.
 * @param {unknown} b Interval list to remove.
