    const orderedIds = kahnOrder(graph).order;
    const source = orderedIds.indexOf(from) > orderedIds.indexOf(to) ? from : to;
    const target = source === from ? to : from;
    if (source === target && !graph[source].includes(target)) graph[source].push(target);
    else if (!graph[source].includes(target)) graph[source].push(target);
