  if (rankA !== rankB) return rankA < rankB ? -1 : 1;
  if (rankA === 1) return compareStrings(a, b);
  if (rankA === 2) return a === b ? 0 : a ? 1 : -1;
  if (a === b) return 0;
  return a < b ? -1 : 1;
