test('comparator and sortIndices agree with sortBy', () => {
  const rows = [{ a: 2, b: 'x' }, { a: 1, b: 'y' }, { a: 2, b: 'a' }];
  const specs = [{ key: 'a' }, { key: 'b', direction: 'desc' }];
