  assert.equal(compare(rows[0], rows[2]) < 0, true);
  assert.equal(compare(rows[0], rows[0]), 0);
  assert.deepEqual(sortIndices(rows, specs), [1, 0, 2]);
  assert.deepEqual(sortBy(rows, specs), sortIndices(rows, specs).map((i) => rows[i]));
});

