/**
 * Intrusive doubly linked list ordered from least- to most-recently used.
 *
 * Every operation is O(1); nodes carry their own links so a caller holding a
 * node can move or drop it without a search.
 */

/** One entry in the recency list. */
export class Node {
  /**
   * @param {string} key Cache key.
   * @param {unknown} value Stored value.
   * @param {number} bytes Size charged to the cache.
   * @param {number} storedAt Clock reading when the entry was stored.
   * @param {number} ttlMs Lifetime in milliseconds, possibly Infinity.
   */
  constructor(key, value, bytes, storedAt, ttlMs) {
    this.key = key;
    this.value = value;
    this.bytes = bytes;
    this.storedAt = storedAt;
    this.ttlMs = ttlMs;
    /** @type {Node | null} */
    this.prev = null;
    /** @type {Node | null} */
    this.next = null;
  }

  /**
   * Reports whether the entry has reached the end of its lifetime.
   * @param {number} now Current clock reading.
   * @returns {boolean} True once `now - storedAt` reaches the lifetime.
   */
  isExpired(now) {
    return now - this.storedAt >= this.ttlMs;
  }
}

/** Doubly linked list whose head is the least-recently used node. */
export class RecencyList {
  constructor() {
    /** @type {Node | null} */
    this.head = null;
    /** @type {Node | null} */
    this.tail = null;
    this.length = 0;
  }

  /**
   * Appends a node as the most-recently used entry.
   * @param {Node} node Node to append.
   * @returns {void}
   */
  append(node) {
    node.prev = this.tail;
    node.next = null;
    if (this.tail === null) this.head = node;
    else this.tail.next = node;
    this.tail = node;
    this.length += 1;
  }

  /**
   * Unlinks a node.
   * @param {Node} node Node to remove.
   * @returns {void}
   */
  remove(node) {
    if (node.prev === null) this.head = node.next;
    else node.prev.next = node.next;
    if (node.next === null) this.tail = node.prev;
    else node.next.prev = node.prev;
    node.prev = null;
    node.next = null;
    this.length -= 1;
  }

  /**
   * Moves a node to the most-recently used end.
   * @param {Node} node Node to move.
   * @returns {void}
   */
  touch(node) {
    if (this.tail === node) return;
    this.remove(node);
    this.append(node);
  }

  /**
   * Walks the list from least- to most-recently used.
   * @yields {Node} Each node in recency order.
   * @returns {Generator<Node>} Iterator over the nodes.
   */
  *[Symbol.iterator]() {
    let node = this.head;
    while (node !== null) {
      const next = node.next;
      yield node;
      node = next;
    }
  }
}

import { Node, RecencyList } from './list.js';

/**
 * Least-recently-used cache with per-entry lifetimes, a byte budget measured
 * by a caller-supplied sizer, and an injectable clock.
 *
 * `get`, `set`, `has`, `peek`, and `delete` are O(1); `prune` and `keys` are
 * linear in the number of stored entries.
 */
export class LruTtlCache {
  /** @type {Map<string, Node>} */
  #nodes = new Map();
  #list = new RecencyList();
  #bytes = 0;
  #maxBytes;
  #ttlMs;
  #clock;
  #sizeOf;
  #onEvict;
  #hits = 0;
  #misses = 0;
  #evictions = 0;
  #expirations = 0;

  /**
   * @param {object} options Cache options.
   * @param {number} options.maxBytes Byte budget; a positive safe integer.
   * @param {number} [options.ttlMs] Default lifetime, `Infinity` by default.
   * @param {() => number} [options.clock] Millisecond clock, `Date.now` by default.
   * @param {(value: unknown, key: string) => number} [options.sizeOf] Sizer, one byte per entry by default.
   * @param {(key: string, value: unknown, reason: string) => void} [options.onEvict] Removal callback.
   */
  constructor(options) {
    if (typeof options !== 'object' || options === null) throw new TypeError('options must be an object');
    const { maxBytes, ttlMs = Number.POSITIVE_INFINITY, clock = Date.now, sizeOf = () => 1, onEvict = () => {} } = options;
    if (!Number.isSafeInteger(maxBytes) || maxBytes <= 0) throw new TypeError('maxBytes must be a positive integer');
    checkTtl(ttlMs);
    if (typeof clock !== 'function') throw new TypeError('clock must be a function');
    if (typeof sizeOf !== 'function') throw new TypeError('sizeOf must be a function');
    if (typeof onEvict !== 'function') throw new TypeError('onEvict must be a function');
    this.#maxBytes = maxBytes;
    this.#ttlMs = ttlMs;
    this.#clock = clock;
    this.#sizeOf = sizeOf;
    this.#onEvict = onEvict;
  }

  /** @returns {number} Byte budget the cache was built with. */
  get capacity() {
    return this.#maxBytes;
  }

  /** @returns {number} Number of stored entries, expired ones included. */
  get size() {
    return this.#nodes.size;
  }

  /** @returns {number} Bytes charged by the stored entries. */
  get bytes() {
    return this.#bytes;
  }

  /**
   * Removes a node from the store and reports it.
   * @param {Node} node Node to drop.
   * @param {string} reason One of `expire`, `size`, `replace`.
   * @returns {void}
   */
  #drop(node, reason) {
    this.#list.remove(node);
    this.#nodes.delete(node.key);
    this.#bytes -= node.bytes;
    if (reason === 'expire') this.#expirations += 1;
    if (reason === 'size') this.#evictions += 1;
    this.#onEvict(node.key, node.value, reason);
  }

  /**
   * Drops a node if its lifetime has ended.
   * @param {Node} node Node to check.
   * @returns {boolean} True when the node was dropped.
   */
  #dropIfExpired(node) {
    if (!node.isExpired(this.#clock())) return false;
    this.#drop(node, 'expire');
    return true;
  }

  /**
   * Stores a value, replacing any entry already under the key.
   * @param {string} key Cache key.
   * @param {unknown} value Value to store.
   * @param {{ttlMs?: number}} [options] Per-entry lifetime override.
   * @returns {boolean} False when the value alone exceeds the byte budget.
   */
  set(key, value, options = {}) {
    checkKey(key);
    if (typeof options !== 'object' || options === null) throw new TypeError('options must be an object');
    const ttlMs = options.ttlMs ?? this.#ttlMs;
    checkTtl(ttlMs);
    const bytes = this.#sizeOf(value, key);
    if (!Number.isSafeInteger(bytes) || bytes < 0) throw new TypeError('sizeOf must return a non-negative safe integer');
    const existing = this.#nodes.get(key);
    if (existing !== undefined) this.#drop(existing, 'replace');
    if (bytes > this.#maxBytes) return false;
    const node = new Node(key, value, bytes, this.#clock(), ttlMs);
    this.#nodes.set(key, node);
    this.#list.append(node);
    this.#bytes += bytes;
    while (this.#bytes > this.#maxBytes) {
      const victim = this.#list.head;
      this.#drop(victim, victim.isExpired(this.#clock()) ? 'expire' : 'size');
    }
    return true;
  }

  /**
   * Reads a value and marks the entry most-recently used.
   * @param {string} key Cache key.
   * @returns {unknown} Stored value, or undefined when absent or expired.
   */
  get(key) {
    checkKey(key);
    const node = this.#nodes.get(key);
    if (node === undefined || this.#dropIfExpired(node)) {
      this.#misses += 1;
      return undefined;
    }
    this.#list.touch(node);
    this.#hits += 1;
    return node.value;
  }

  /**
   * Reads a value without changing recency or hit counters.
   * @param {string} key Cache key.
   * @returns {unknown} Stored value, or undefined when absent or expired.
   */
  peek(key) {
    checkKey(key);
    const node = this.#nodes.get(key);
    if (node === undefined || this.#dropIfExpired(node)) return undefined;
    return node.value;
  }

  /**
   * Reports whether a live entry is stored, without changing recency or hit
   * counters.
   * @param {string} key Cache key.
   * @returns {boolean} True when a live entry exists.
   */
  has(key) {
    checkKey(key);
    const node = this.#nodes.get(key);
    return node !== undefined && !this.#dropIfExpired(node);
  }

  /**
   * Removes an entry without reporting it.
   * @param {string} key Cache key.
   * @returns {boolean} True when an entry was removed.
   */
  delete(key) {
    checkKey(key);
    const node = this.#nodes.get(key);
    if (node === undefined) return false;
    this.#list.remove(node);
    this.#nodes.delete(key);
    this.#bytes -= node.bytes;
    return true;
  }

  /**
   * Removes every entry without reporting any of them.
   * @returns {void}
   */
  clear() {
    this.#nodes = new Map();
    this.#list = new RecencyList();
    this.#bytes = 0;
  }

  /**
   * Removes every entry whose lifetime has ended.
   * @returns {number} How many entries were removed.
   */
  prune() {
    const now = this.#clock();
    let removed = 0;
    for (const node of this.#list) {
      if (node.isExpired(now)) {
        this.#drop(node, 'expire');
        removed += 1;
      }
    }
    return removed;
  }

  /**
   * Lists the live keys after pruning expired entries.
   * @returns {string[]} Keys from least- to most-recently used.
   */
  keys() {
    this.prune();
    return [...this.#list].map((node) => node.key);
  }

  /**
   * Reports cumulative counters.
   * @returns {{hits: number, misses: number, evictions: number, expirations: number}} Counters.
   */
  stats() {
    return { hits: this.#hits, misses: this.#misses, evictions: this.#evictions, expirations: this.#expirations };
  }
}

/**
 * Validates a cache key.
 * @param {unknown} key Candidate key.
 * @returns {void}
 * @throws {TypeError} When the key is not a string.
 */
function checkKey(key) {
  if (typeof key !== 'string') throw new TypeError('key must be a string');
}

/**
 * Validates a lifetime.
 * @param {unknown} ttlMs Candidate lifetime.
 * @returns {void}
 * @throws {TypeError} When the lifetime is not a non-negative number.
 */
function checkTtl(ttlMs) {
  if (typeof ttlMs !== 'number' || Number.isNaN(ttlMs) || ttlMs < 0) {
    throw new TypeError('ttlMs must be a non-negative number');
  }
}

import { test } from 'node:test';
import assert from 'node:assert/strict';

import { LruTtlCache } from '../src/cache.js';

/**
 * Deterministic 32-bit PRNG.
 * @param {number} seed Initial state.
 * @returns {() => number} Generator returning floats in [0, 1).
 */
function mulberry32(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * Builds a cache with a hand-driven clock and an eviction log.
 * @param {object} options Cache options without the clock.
 * @returns {{cache: LruTtlCache, log: Array<[string, unknown, string]>, advance: (ms: number) => void, now: () => number}} Harness.
 */
function harness(options) {
  let time = 0;
  const log = [];
  const cache = new LruTtlCache({
    ...options,
    clock: () => time,
    onEvict: (key, value, reason) => log.push([key, value, reason]),
  });
  return { cache, log, advance: (ms) => { time += ms; }, now: () => time };
}

test('evicts the least recently used entry when the byte budget is exceeded', () => {
  const { cache, log } = harness({ maxBytes: 3 });
  assert.equal(cache.set('a', 1), true);
  cache.set('b', 2);
  cache.set('c', 3);
  assert.deepEqual(cache.keys(), ['a', 'b', 'c']);
  assert.equal(cache.get('a'), 1);
  assert.deepEqual(cache.keys(), ['b', 'c', 'a']);
  cache.set('d', 4);
  assert.deepEqual(cache.keys(), ['c', 'a', 'd']);
  assert.deepEqual(log, [['b', 2, 'size']]);
  assert.equal(cache.size, 3);
  assert.equal(cache.bytes, 3);
  assert.equal(cache.capacity, 3);
});

test('charges the sizer and evicts until the total fits', () => {
  const { cache, log } = harness({ maxBytes: 10, sizeOf: (value) => value.length });
  cache.set('x', '12345');
  cache.set('y', '12345');
  assert.equal(cache.bytes, 10);
  cache.set('z', '1');
  assert.deepEqual(cache.keys(), ['y', 'z']);
  assert.equal(cache.bytes, 6);
  assert.deepEqual(log, [['x', '12345', 'size']]);
  cache.set('big', '0123456789');
  assert.deepEqual(cache.keys(), ['big']);
  assert.equal(cache.bytes, 10);
  assert.equal(cache.set('huge', '0123456789A'), false);
  assert.deepEqual(cache.keys(), ['big']);
  assert.equal(cache.set('big', '0123456789A'), false);
  assert.deepEqual(cache.keys(), []);
  assert.equal(cache.bytes, 0);
