test('rejects malformed options and keys', () => {
  assert.throws(() => new LruTtlCache(), { name: 'TypeError', message: 'options must be an object' });
  assert.throws(() => new LruTtlCache({ maxBytes: 0 }), { name: 'TypeError', message: 'maxBytes must be a positive integer' });
  assert.throws(() => new LruTtlCache({ maxBytes: 1.5 }), { name: 'TypeError', message: 'maxBytes must be a positive integer' });
  assert.throws(() => new LruTtlCache({ maxBytes: Number.POSITIVE_INFINITY }), { name: 'TypeError', message: 'maxBytes must be a positive integer' });
  assert.throws(() => new LruTtlCache({ maxBytes: 4, ttlMs: -1 }), { name: 'TypeError', message: 'ttlMs must be a non-negative number' });
  assert.throws(() => new LruTtlCache({ maxBytes: 4, ttlMs: '10' }), { name: 'TypeError', message: 'ttlMs must be a non-negative number' });
  assert.throws(() => new LruTtlCache({ maxBytes: 4, clock: 0 }), { name: 'TypeError', message: 'clock must be a function' });
