  const { cache } = harness({ maxBytes: 4, sizeOf: (value) => value });
  assert.throws(() => cache.set(7, 1), { name: 'TypeError', message: 'key must be a string' });
  assert.throws(() => cache.get(null), { name: 'TypeError', message: 'key must be a string' });
