test('holds every invariant across a long random operation sequence', () => {
  const rnd = mulberry32(0xca11ab1e);
  const keyPool = ['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h'];
  const sizeOf = (value) => (value % 4) + 1;
  let time = 0;
  const log = [];
  const cache = new LruTtlCache({
    maxBytes: 12,
    ttlMs: 90,
    clock: () => time,
    sizeOf,
    onEvict: (key, value, reason) => log.push([key, value, reason]),
  });

  /** @type {Array<{key: string, value: number, bytes: number, storedAt: number, ttlMs: number}>} */
  let model = [];
  const modelLog = [];
  const counters = { hits: 0, misses: 0, evictions: 0, expirations: 0 };
  let modelBytes = 0;
  const expired = (entry) => time - entry.storedAt >= entry.ttlMs;
  const drop = (entry, reason) => {
    model = model.filter((other) => other !== entry);
    modelBytes -= entry.bytes;
    if (reason === 'expire') counters.expirations += 1;
    if (reason === 'size') counters.evictions += 1;
    modelLog.push([entry.key, entry.value, reason]);
  };
  const find = (key) => model.find((entry) => entry.key === key);

  for (let step = 0; step < 4000; step += 1) {
    const key = keyPool[Math.floor(rnd() * keyPool.length)];
    const roll = rnd();
    if (roll < 0.42) {
      const value = Math.floor(rnd() * 20);
      const ttlMs = rnd() < 0.25 ? Math.floor(rnd() * 60) : 90;
      cache.set(key, value, { ttlMs });
      const bytes = sizeOf(value);
      const existing = find(key);
      if (existing !== undefined) drop(existing, 'replace');
      if (bytes <= 12) {
        model.push({ key, value, bytes, storedAt: time, ttlMs });
        modelBytes += bytes;
        while (modelBytes > 12) drop(model[0], expired(model[0]) ? 'expire' : 'size');
      }
    } else if (roll < 0.72) {
      const entry = find(key);
      let expect;
      if (entry === undefined) {
        counters.misses += 1;
      } else if (expired(entry)) {
        drop(entry, 'expire');
        counters.misses += 1;
      } else {
        model = model.filter((other) => other !== entry).concat(entry);
        counters.hits += 1;
        expect = entry.value;
      }
      assert.equal(cache.get(key), expect, `get ${key} at step ${step}`);
    } else if (roll < 0.8) {
      const entry = find(key);
      if (entry !== undefined && expired(entry)) drop(entry, 'expire');
      assert.equal(cache.has(key), entry !== undefined && !expired(entry), `has ${key} at step ${step}`);
    } else if (roll < 0.86) {
      const entry = find(key);
      if (entry !== undefined) {
        model = model.filter((other) => other !== entry);
        modelBytes -= entry.bytes;
      }
      assert.equal(cache.delete(key), entry !== undefined, `delete ${key} at step ${step}`);
    } else if (roll < 0.92) {
      for (const entry of [...model]) {
        if (expired(entry)) drop(entry, 'expire');
      }
      assert.deepEqual(cache.keys(), model.map((entry) => entry.key), `keys at step ${step}`);
    } else {
      time += 1 + Math.floor(rnd() * 40);
    }
    assert.equal(cache.size, model.length, `size at step ${step}`);
    assert.equal(cache.bytes, modelBytes, `bytes at step ${step}`);
  }

  assert.deepEqual(cache.stats(), counters);
  assert.deepEqual(log, modelLog);
  assert.ok(counters.evictions > 50, `expected real eviction pressure, saw ${counters.evictions}`);
  assert.ok(counters.expirations > 50, `expected real expiry pressure, saw ${counters.expirations}`);
  assert.deepEqual(cache.keys(), model.filter((entry) => !expired(entry)).map((entry) => entry.key));
});

/**
 * Least-recently-used cache with per-entry lifetimes, a byte budget measured
 * by a caller-supplied sizer, and an injectable clock.
 *
 * This starting point stores entries in insertion order and ignores lifetimes,
 * the byte budget, recency, and the eviction callback.
 */
export class LruTtlCache {
  /** @type {Map<string, unknown>} */
  #values = new Map();
  #maxBytes;

  /**
   * @param {object} options Cache options.
   * @param {number} options.maxBytes Byte budget; a positive safe integer.
   * @param {number} [options.ttlMs] Default lifetime, `Infinity` by default.
   * @param {() => number} [options.clock] Millisecond clock, `Date.now` by default.
   * @param {(value: unknown, key: string) => number} [options.sizeOf] Sizer, one byte per entry by default.
   * @param {(key: string, value: unknown, reason: string) => void} [options.onEvict] Removal callback.
   */
  constructor(options) {
    this.#maxBytes = options.maxBytes;
  }

  /** @returns {number} Byte budget the cache was built with. */
  get capacity() {
    return this.#maxBytes;
  }

  /** @returns {number} Number of stored entries, expired ones included. */
  get size() {
    return this.#values.size;
  }

  /** @returns {number} Bytes charged by the stored entries. */
  get bytes() {
    return this.#values.size;
  }

  /**
   * Stores a value, replacing any entry already under the key.
   * @param {string} key Cache key.
   * @param {unknown} value Value to store.
   * @param {{ttlMs?: number}} [options] Per-entry lifetime override.
   * @returns {boolean} False when the value alone exceeds the byte budget.
   */
  set(key, value, options = {}) {
    this.#values.set(key, value);
    return true;
  }

  /**
   * Reads a value and marks the entry most-recently used.
   * @param {string} key Cache key.
   * @returns {unknown} Stored value, or undefined when absent or expired.
   */
  get(key) {
    return this.#values.get(key);
  }

  /**
   * Reads a value without changing recency or hit counters.
   * @param {string} key Cache key.
   * @returns {unknown} Stored value, or undefined when absent or expired.
   */
  peek(key) {
    return this.#values.get(key);
  }

  /**
   * Reports whether a live entry is stored, without changing recency or hit
   * counters.
   * @param {string} key Cache key.
   * @returns {boolean} True when a live entry exists.
   */
  has(key) {
    return this.#values.has(key);
  }

  /**
   * Removes an entry without reporting it.
   * @param {string} key Cache key.
   * @returns {boolean} True when an entry was removed.
   */
  delete(key) {
    return this.#values.delete(key);
  }

  /**
   * Removes every entry without reporting any of them.
   * @returns {void}
   */
  clear() {
    this.#values.clear();
  }

  /**
   * Removes every entry whose lifetime has ended.
   * @returns {number} How many entries were removed.
   */
  prune() {
    return 0;
  }

  /**
   * Lists the live keys after pruning expired entries.
   * @returns {string[]} Keys from least- to most-recently used.
   */
  keys() {
    return [...this.#values.keys()];
  }

  /**
   * Reports cumulative counters.
   * @returns {{hits: number, misses: number, evictions: number, expirations: number}} Counters.
   */
  stats() {
    return { hits: 0, misses: 0, evictions: 0, expirations: 0 };
  }
}

