import { test } from 'node:test';
import assert from 'node:assert/strict';

import { IndexedHeap } from '../src/heap.js';

/**
 * Deterministic 32-bit PRNG.
 * @param {number} seed Initial state.
 * @returns {() => number} Generator returning floats in [0, 1).
 */
function mulberry32(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

test('an empty heap reports nothing', () => {
  const heap = new IndexedHeap();
  assert.equal(heap.size, 0);
  assert.equal(heap.peek(), undefined);
  assert.equal(heap.pop(), undefined);
  assert.deepEqual(heap.drain(), []);
  assert.equal(heap.has('nope'), false);
  assert.equal(heap.priorityOf('nope'), undefined);
  assert.equal(heap.remove('nope'), false);
});

test('entries leave in priority order', () => {
  const heap = new IndexedHeap();
  for (const [key, priority] of [['e', 5], ['a', 1], ['d', 4], ['c', 3], ['b', 2]]) heap.push(key, priority);
  assert.equal(heap.size, 5);
  assert.deepEqual(heap.peek(), { key: 'a', priority: 1 });
  assert.deepEqual(heap.pop(), { key: 'a', priority: 1 });
  assert.deepEqual(heap.drain().map((entry) => entry.key), ['b', 'c', 'd', 'e']);
  assert.equal(heap.size, 0);
  const negatives = new IndexedHeap();
  for (const [key, priority] of [['zero', 0], ['neg', -3.5], ['pos', 0.5]]) negatives.push(key, priority);
  assert.deepEqual(negatives.drain(), [
    { key: 'neg', priority: -3.5 },
    { key: 'zero', priority: 0 },
    { key: 'pos', priority: 0.5 },
  ]);
});

test('equal priorities leave in insertion order', () => {
  const heap = new IndexedHeap();
  for (const key of ['p', 'q', 'r', 's', 't', 'u', 'v']) heap.push(key, 5);
  assert.deepEqual(heap.drain().map((entry) => entry.key), ['p', 'q', 'r', 's', 't', 'u', 'v']);
  const mixed = new IndexedHeap();
  for (const [key, priority] of [['a', 2], ['b', 1], ['c', 2], ['d', 1], ['e', 2]]) mixed.push(key, priority);
  assert.deepEqual(mixed.drain().map((entry) => entry.key), ['b', 'd', 'a', 'c', 'e']);
});

test('re-prioritising keeps the original insertion number', () => {
  const heap = new IndexedHeap();
  for (const key of ['x', 'y', 'z']) heap.push(key, 1);
  heap.setPriority('x', 9);
  assert.deepEqual(heap.peek(), { key: 'y', priority: 1 });
  heap.setPriority('x', 1);
  assert.deepEqual(heap.drain().map((entry) => entry.key), ['x', 'y', 'z']);
  const again = new IndexedHeap();
  for (const key of ['x', 'y', 'z']) again.push(key, 1);
  again.decreaseKey('z', 1);
  assert.deepEqual(again.drain().map((entry) => entry.key), ['x', 'y', 'z']);
});

test('decreaseKey lowers a priority and refuses to raise one', () => {
  const heap = new IndexedHeap();
  for (const [key, priority] of [['a', 10], ['b', 20], ['c', 30], ['d', 40]]) heap.push(key, priority);
  heap.decreaseKey('d', 5);
  assert.deepEqual(heap.peek(), { key: 'd', priority: 5 });
  assert.equal(heap.priorityOf('d'), 5);
  assert.throws(() => heap.decreaseKey('d', 6), { name: 'RangeError', message: 'priority must not increase for "d"' });
  assert.throws(() => heap.decreaseKey('gone', 1), { name: 'ReferenceError', message: 'unknown key: "gone"' });
  assert.throws(() => heap.setPriority('gone', 1), { name: 'ReferenceError', message: 'unknown key: "gone"' });
  heap.setPriority('a', 99);
  assert.deepEqual(heap.drain().map((entry) => entry.key), ['d', 'b', 'c', 'a']);
});

test('remove takes an entry from anywhere and keeps the order intact', () => {
  const heap = new IndexedHeap();
  for (const [key, priority] of [['a', 1], ['b', 2], ['c', 3], ['d', 4], ['e', 5], ['f', 6], ['g', 7]]) {
    heap.push(key, priority);
  }
  assert.equal(heap.remove('a'), true);
  assert.equal(heap.remove('g'), true);
  assert.equal(heap.remove('d'), true);
  assert.equal(heap.remove('d'), false);
  assert.deepEqual([heap.size, heap.has('d'), heap.priorityOf('c')], [4, false, 3]);
  assert.deepEqual(heap.drain().map((entry) => entry.key), ['b', 'c', 'e', 'f']);
  const single = new IndexedHeap();
  single.push('only', 1);
  assert.equal(single.remove('only'), true);
  assert.deepEqual([single.size, single.peek()], [0, undefined]);
});

test('rejects malformed keys and priorities', () => {
  const heap = new IndexedHeap();
  heap.push('a', 1);
  assert.throws(() => heap.push('a', 2), { name: 'Error', message: 'duplicate key: "a"' });
  assert.throws(() => heap.push(1, 1), { name: 'TypeError', message: 'key must be a string' });
  assert.throws(() => heap.has(null), { name: 'TypeError', message: 'key must be a string' });
  assert.throws(() => heap.push('b', Number.NaN), { name: 'TypeError', message: 'priority must be a finite number' });
  assert.throws(() => heap.push('b', Number.POSITIVE_INFINITY), { name: 'TypeError', message: 'priority must be a finite number' });
  assert.throws(() => heap.push('b', '5'), { name: 'TypeError', message: 'priority must be a finite number' });
  assert.throws(() => heap.decreaseKey('a', Number.NaN), { name: 'TypeError', message: 'priority must be a finite number' });
  assert.deepEqual([heap.size, heap.has('b')], [1, false]);
});

test('matches a naive model across a long random operation sequence', () => {
  const rnd = mulberry32(0x1e4d);
  const keyPool = Array.from({ length: 24 }, (_, i) => `k${String(i).padStart(2, '0')}`);
  const heap = new IndexedHeap();
  /** @type {Array<{key: string, priority: number, seq: number}>} */
  let model = [];
  let seq = 0;
  const best = () => {
    let winner = null;
    for (const item of model) {
      if (winner === null || item.priority < winner.priority || (item.priority === winner.priority && item.seq < winner.seq)) {
        winner = item;
      }
    }
    return winner;
  };

  for (let step = 0; step < 6000; step += 1) {
    const key = keyPool[Math.floor(rnd() * keyPool.length)];
    const held = model.find((item) => item.key === key);
    const roll = rnd();
    if (roll < 0.4) {
      const priority = Math.floor(rnd() * 8);
      if (held === undefined) {
        heap.push(key, priority);
        seq += 1;
        model.push({ key, priority, seq });
      } else {
        assert.throws(() => heap.push(key, priority), { name: 'Error', message: `duplicate key: "${key}"` }, `step ${step}`);
      }
    } else if (roll < 0.65) {
      const winner = best();
      const popped = heap.pop();
      if (winner === null) assert.equal(popped, undefined, `step ${step}`);
      else {
        assert.deepEqual(popped, { key: winner.key, priority: winner.priority }, `pop at step ${step}`);
        model = model.filter((item) => item !== winner);
      }
    } else if (roll < 0.8 && held !== undefined) {
      const priority = held.priority - Math.floor(rnd() * 4);
      heap.decreaseKey(key, priority);
      held.priority = priority;
    } else if (roll < 0.9 && held !== undefined) {
      const priority = Math.floor(rnd() * 12) - 2;
      heap.setPriority(key, priority);
      held.priority = priority;
    } else {
      assert.equal(heap.remove(key), held !== undefined, `remove at step ${step}`);
      model = model.filter((item) => item !== held);
    }
    assert.deepEqual([heap.size, heap.priorityOf(key)], [model.length, model.find((i) => i.key === key)?.priority], `state at step ${step}`);
  }

  const drained = heap.drain();
  const expected = [...model].sort((a, b) => a.priority - b.priority || a.seq - b.seq);
  assert.deepEqual(drained, expected.map(({ key, priority }) => ({ key, priority })));
  assert.deepEqual([heap.size, heap.pop()], [0, undefined]);
});

import { test } from 'node:test';
import assert from 'node:assert/strict';

import { shortestPath, shortestPaths } from '../src/dijkstra.js';

/** Infinity, as it appears in a distance map. */
const FAR = Number.POSITIVE_INFINITY;

/**
 * Deterministic 32-bit PRNG.
 * @param {number} seed Initial state.
 * @returns {() => number} Generator returning floats in [0, 1).
 */
function mulberry32(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * Computes distances with Bellman-Ford as an independent model.
 * @param {Record<string, Record<string, number>>} graph Weighted graph.
 * @param {string} source Start node.
 * @returns {Record<string, number>} Distance per node.
 */
function bellmanFord(graph, source) {
  const nodes = Object.keys(graph);
  const dist = {};
  for (const node of nodes) dist[node] = FAR;
  dist[source] = 0;
  for (let round = 0; round < nodes.length; round += 1) {
    for (const node of nodes) {
      if (dist[node] === FAR) continue;
      for (const [target, weight] of Object.entries(graph[node])) {
        if (dist[node] + weight < dist[target]) dist[target] = dist[node] + weight;
      }
    }
  }
  return dist;
}

/** Small hand-checked graph. */
const graph = {
  a: { b: 1, c: 4 },
  b: { c: 2, d: 6 },
  c: { d: 3 },
  d: {},
  island: {},
};

test('computes distances and predecessors from one source', () => {
  const { dist, prev } = shortestPaths(graph, 'a');
  assert.deepEqual(dist, { a: 0, b: 1, c: 3, d: 6, island: FAR });
  assert.deepEqual(prev, { a: null, b: 'a', c: 'b', d: 'c', island: null });
  assert.deepEqual(shortestPaths(graph, 'c').dist, { a: FAR, b: FAR, c: 0, d: 3, island: FAR });
  assert.deepEqual(shortestPaths(graph, 'd').prev, { a: null, b: null, c: null, d: null, island: null });
});

test('reconstructs a route or reports that none exists', () => {
  assert.deepEqual(shortestPath(graph, 'a', 'd'), { distance: 6, path: ['a', 'b', 'c', 'd'] });
  assert.deepEqual(shortestPath(graph, 'a', 'a'), { distance: 0, path: ['a'] });
  assert.deepEqual(shortestPath(graph, 'b', 'd'), { distance: 5, path: ['b', 'c', 'd'] });
  assert.equal(shortestPath(graph, 'a', 'island'), null);
  assert.equal(shortestPath(graph, 'd', 'a'), null);
});

test('ties pick the smallest predecessor', () => {
  const tie = { s: { m: 2, n: 2 }, m: { t: 3 }, n: { t: 3 }, t: {} };
  assert.deepEqual(shortestPaths(tie, 's').prev, { s: null, m: 's', n: 's', t: 'm' });
  assert.deepEqual(shortestPath(tie, 's', 't'), { distance: 5, path: ['s', 'm', 't'] });
  const flipped = { s: { n: 2, m: 2 }, n: { t: 3 }, m: { t: 3 }, t: {} };
  assert.deepEqual(shortestPath(flipped, 's', 't'), { distance: 5, path: ['s', 'm', 't'] });
});

test('rejects malformed graphs and unknown endpoints', () => {
  const bad = [
    [() => shortestPaths(null, 'a'), 'TypeError', 'graph must be an object'],
    [() => shortestPaths([{ a: 1 }], 'a'), 'TypeError', 'graph must be an object'],
    [() => shortestPaths({ a: ['b'], b: {} }, 'a'), 'TypeError', 'edge map for node "a" must be an object'],
    [() => shortestPaths({ a: { q: 1 } }, 'a'), 'ReferenceError', 'unknown node: "q"'],
    [() => shortestPaths({ a: { b: 0 }, b: {} }, 'a'), 'RangeError', 'weight must be positive: "a" -> "b"'],
    [() => shortestPaths({ a: { b: -2 }, b: {} }, 'a'), 'RangeError', 'weight must be positive: "a" -> "b"'],
    [() => shortestPaths({ a: { b: '3' }, b: {} }, 'a'), 'RangeError', 'weight must be positive: "a" -> "b"'],
    [() => shortestPaths(graph, 'zz'), 'ReferenceError', 'unknown node: "zz"'],
    [() => shortestPath(graph, 'a', 'zz'), 'ReferenceError', 'unknown node: "zz"'],
    [() => shortestPaths(graph, 7), 'TypeError', 'source must be a string'],
  ];
  for (const [call, name, message] of bad) assert.throws(call, { name, message }, message);
});

test('agrees with Bellman-Ford on random weighted graphs', () => {
  const rnd = mulberry32(0xd1357a);
  for (let round = 0; round < 60; round += 1) {
    const size = 5 + Math.floor(rnd() * 8);
    const ids = Array.from({ length: size }, (_, i) => `n${String(i).padStart(2, '0')}`);
    const random = {};
    for (const id of ids) random[id] = {};
    for (const from of ids) {
      for (const to of ids) {
        if (from !== to && rnd() < 0.3) random[from][to] = 1 + Math.floor(rnd() * 9);
      }
    }
    const source = ids[Math.floor(rnd() * ids.length)];
    const { dist, prev } = shortestPaths(random, source);
    assert.deepEqual(dist, bellmanFord(random, source), `round ${round}`);
    assert.equal(prev[source], null, `round ${round} source predecessor`);
    for (const node of ids) {
      if (node === source || dist[node] === FAR) {
        assert.equal(prev[node], node === source ? null : null, `round ${round} ${node} unreachable`);
        continue;
      }
      const candidates = ids.filter((from) => random[from][node] !== undefined && dist[from] + random[from][node] === dist[node]);
      assert.equal(prev[node], candidates.sort()[0], `round ${round} predecessor of ${node}`);
      const route = shortestPath(random, source, node);
      let walked = 0;
      for (let i = 1; i < route.path.length; i += 1) walked += random[route.path[i - 1]][route.path[i]];
      assert.deepEqual([route.distance, walked, route.path[0]], [dist[node], dist[node], source], `round ${round} route to ${node}`);
    }
  }
});

